<?php $pageTitle='My Bharatpur'; require __DIR__.'/includes/header.php'; ?>
<section class="page-hero"><div class="container"><div class="section-kicker">Your collection</div><h1 class="display-4 fw-bold">My Bharatpur</h1><p class="muted">Saved places and itineraries are kept in this browser for the hackathon prototype.</p></div></section>
<section class="pb-5"><div class="container"><div id="savedRoot"></div></div></section>
<script>
function renderSaved(){const root=document.getElementById('savedRoot'),items=BharatpurApp.saved(),trip=JSON.parse(localStorage.getItem('bharatpur_itinerary')||'null');let html='';if(trip){html+=`<div class="detail-panel mb-4"><span class="badge-soft">Saved itinerary</span><h3 class="mt-2">${trip.title}</h3><p class="muted">${trip.prefs.days} days • ${trip.prefs.group} • ${trip.prefs.interests.join(' + ')}</p><strong>Estimated activities: NPR ${Number(trip.total).toLocaleString()}</strong></div>`}if(!items.length){html+=`<div class="saved-empty"><i class="fa-regular fa-heart fs-1 text-success mb-3"></i><h3>No saved places yet</h3><p class="muted">Explore Bharatpur and tap the heart on places you want to remember.</p><a class="btn btn-brand" href="explore.php">Start exploring</a></div>`}else{html+='<div class="row g-4">'+items.map(p=>`<div class="col-md-6 col-lg-4"><div class="tour-card"><div class="image-wrap"><img src="${p.image}"></div><div class="content"><span class="badge-soft">${p.category}</span><h4 class="mt-2">${p.name}</h4><strong>NPR ${Number(p.cost).toLocaleString()}</strong><div class="d-flex gap-2 mt-3"><a class="btn btn-outline-brand" href="destination.php?id=${p.id}">View</a><button class="btn btn-light fw-bold remove-save" data-id="${p.id}">Remove</button></div></div></div></div>`).join('')+'</div>'}root.innerHTML=html;document.querySelectorAll('.remove-save').forEach(b=>b.onclick=()=>{const p=items.find(x=>String(x.id)===b.dataset.id);if(p)BharatpurApp.toggleSave(p);renderSaved()})}document.addEventListener('DOMContentLoaded',renderSaved);
</script>
<?php require __DIR__.'/includes/footer.php'; ?>
